  'This course examines how mass media institutions, technologies, industries, texts, platforms, and audiences shape society. Students study media history, print, audio, film, television, streaming, digital platforms, journalism, advertising, PR, ownership, policy, regulation, representation, media effects, global flows, misinformation, ethics, law, media literacy, and public life through theory, case analysis, research evidence, and media criticism.',
  $mmsojson${"slug": "mass-media-and-society", "title": "Mass Media and Society", "description": "This course examines how mass media institutions, technologies, industries, texts, platforms, and audiences shape society. Students study media history, print, audio, film, television, streaming, digital platforms, journalism, advertising, PR, ownership, policy, regulation, representation, media effects, global flows, misinformation, ethics, law, media literacy, and public life through theory, case analysis, research evidence, and media criticism.", "topics": [{"id": "75e78956-61c3-4a25-bcc9-a1ffe39a8289", "type": "topic", "title": "Mass Media and Society Foundations: Media Systems, Institutions, and Public Life", "description": "Students learn how media institutions organize culture, information, power, identity, and civic life.", "children": [{"id": "86654760-63c9-4f80-a673-ad503ec49339", "type": "subtopic", "title": "Media as institutions", "children": [{"id": "e990a3a7-42e8-4af4-91c2-3e8855559537", "type": "concept", "title": "Media organizations, industries, professions, and infrastructures"}, {"id": "22c9f8b3-49b2-4319-8366-d58710bfc467", "type": "concept", "title": "Production, distribution, audiences, and feedback loops"}, {"id": "678f9211-c858-49af-b5e4-8b5a3386d7e5", "type": "concept", "title": "Institutional power and public dependence"}], "description": "The point is to see media as organized systems, not just content."}, {"id": "6cc979bf-6eb2-43ad-9a73-31d65f9d9a88", "type": "subtopic", "title": "Society and culture", "children": [{"id": "34d568cd-8e64-4504-8690-de634f840e3b", "type": "concept", "title": "Culture, identity, norms, values, and social imagination"}, {"id": "fb885450-aba0-40f1-be93-ba9dfd0fb8e4", "type": "concept", "title": "Media rituals, habits, and social connection"}, {"id": "accfc900-5af7-4b05-bbb0-fee059e0d3b8", "type": "concept", "title": "Public discourse and cultural conflict"}], "description": "Students learn how media participate in shared meaning and everyday life."}, {"id": "fcd471fb-550c-412b-a1e6-7c3e7364b646", "type": "subtopic", "title": "Public life", "children": [{"id": "3dffe80c-0c9c-428c-88e3-dfe160cc40f3", "type": "concept", "title": "Democracy, citizenship, accountability, and public spheres"}, {"id": "dd6f23df-98f9-4f33-ab9a-e2196c1ed1ab", "type": "concept", "title": "Agenda-setting and social visibility"}, {"id": "def356e5-d133-4033-813e-f7abd37c947e", "type": "concept", "title": "Media access, exclusion, and participation"}], "description": "Mass media shape what societies know, debate, and remember."}]}, {"id": "40f5b49c-0cd5-438c-813a-1b6d74c7f0b8", "type": "topic", "title": "Media History and Technological Change from Print to Platforms", "description": "This topic traces how media technologies and institutions changed society from print through streaming and platforms.", "children": [{"id": "7c3c074f-5689-41a8-9e36-f87b4244b4eb", "type": "subtopic", "title": "Historical development", "children": [{"id": "76b7f02c-251c-4b35-89de-a00102d822eb", "type": "concept", "title": "Printing press, newspapers, telegraph, photography, radio, film, TV, internet, mobile, and platforms"}, {"id": "774063c7-9e5c-4f28-873c-27a6bfc313f6", "type": "concept", "title": "Convergence and remediation"}, {"id": "523b7937-698e-4757-bbb9-d9d02382a817", "type": "concept", "title": "Media revolutions and continuity"}], "description": "Students track how media forms emerge from social, economic, and technological change."}, {"id": "fef85a0a-114f-44c4-aeb1-b1ad4e07d3a3", "type": "subtopic", "title": "Technology and society", "children": [{"id": "54ffdb20-6e64-4554-a3e7-1fc4a2efa5f2", "type": "concept", "title": "Affordances, constraints, infrastructures, and adoption"}, {"id": "f2b89661-5049-4922-a3ee-232cf8e79af6", "type": "concept", "title": "Media ecology and McLuhan"}, {"id": "7dab7125-2373-4586-ae22-c801a5459b26", "type": "concept", "title": "Social shaping of technology"}], "description": "The gist is to avoid technological determinism while still taking technology seriously."}, {"id": "51abdb3e-302c-4d4b-aa6e-a9811c22c926", "type": "subtopic", "title": "Institutional change", "children": [{"id": "8cda81bd-109c-45e2-b37c-80b2363c144b", "type": "concept", "title": "Professionalization, commercialization, consolidation, and fragmentation"}, {"id": "9b3cdedb-b21b-4087-9604-7dc61cc0a9c1", "type": "concept", "title": "From mass audience to segmented publics"}, {"id": "0d878681-63b8-408d-9118-ac8bc52b23fa", "type": "concept", "title": "Legacy media, digital-native media, and creator media"}], "description": "Media history helps explain contemporary disruption."}]}, {"id": "7de13047-b67b-4ab6-bd5a-02519a98141a", "type": "topic", "title": "Print Media, Publishing, Newspapers, Magazines, and the Public Sphere", "description": "Students study print as a foundation for journalism, literacy, public debate, and modern media economics.", "children": [{"id": "21086076-b3ec-48e7-b4a6-107bf163a837", "type": "subtopic", "title": "Newspapers and journalism", "children": [{"id": "afaacb79-2aac-46ba-8c93-381a540c3d73", "type": "concept", "title": "Penny press, partisan press, watchdog journalism, and local news"}, {"id": "abff51d8-d351-4bc1-be95-d9908e1a9f89", "type": "concept", "title": "Objectivity, beats, sourcing, and editorial judgment"}, {"id": "b1da24af-f862-4bb4-b39c-c85b117da470", "type": "concept", "title": "Decline, consolidation, nonprofit news, and local news deserts"}], "description": "Students study newspapers as civic institutions and business models."}, {"id": "8d871ae9-6c15-4b59-8dd7-48baba0e8670", "type": "subtopic", "title": "Books, magazines, and publishing", "children": [{"id": "a5b669fd-f65a-40a2-a610-2d34262c5281", "type": "concept", "title": "Book publishing, magazines, zines, and literary publics"}, {"id": "245ed725-56e5-4e48-a957-c9b10e41f6cf", "type": "concept", "title": "Gatekeeping, authorship, censorship, and distribution"}, {"id": "68971ffd-9310-48cb-