update public.learning_paths
set
  title = 'Mass Media and Society',
  goal = 'Mass Media and Society',
  summary = 'This course examines how mass media institutions, technologies, industries, texts, platforms, and audiences shape society. Students study media history, print, audio, film, television, streaming, digital platforms, journalism, advertising, PR, ownership, policy, regulation, representation, media effects, global flows, misinformation, ethics, law, media literacy, and public life through theory, case analysis, research evidence, and media criticism.',
  data = $mmsojson${"slug": "mass-media-and-society", "title": "Mass Media and Society", "description": "This course examines how mass media institutions, technologies, industries, texts, platforms, and audiences shape society. Students study media history, print, audio, film, television, streaming, digital platforms, journalism, advertising, PR, ownership, policy, regulation, representation, media effects, global flows, misinformation, ethics, law, media literacy, and public life through theory, case analysis, research evidence, and media criticism.", "topics": [{"id": "75e78956-61c3-4a25-bcc9-a1ffe39a8289", "type": "topic", "title": "Mass Media and Society Foundations: Media Systems, Institutions, and Public Life", "description": "Students learn how media institutions organize culture, information, power, identity, and civic life.", "children": [{"id": "86654760-63c9-4f80-a673-ad503ec49339", "type": "subtopic", "title": "Media as institutions", "children": [{"id": "e990a3a7-42e8-4af4-91c2-3e8855559537", "type": "concept", "title": "Media organizations, industries, professions, and infrastructures"}, {"id": "22c9f8b3-49b2-4319-8366-d58710bfc467", "type": "concept", "title": "Production, distribution, audiences, and feedback loops"}, {"id": "678f9211-c858-49af-b5e4-8b5a3386d7e5", "type": "concept", "title": "Institutional power and public dependence"}], "description": "The point is to see media as organized systems, not just content."}, {"id": "6cc979bf-6eb2-43ad-9a73-31d65f9d9a88", "type": "subtopic", "title": "Society and culture", "children": [{"id": "34d568cd-8e64-4504-8690-de634f840e3b", "type": "concept", "title": "Culture, identity, norms, values, and social imagination"}, {"id": "fb885450-aba0-40f1-be93-ba9dfd0fb8e4", "type": "concept", "title": "Media rituals, habits, and social connection"}, {"id": "accfc900-5af7-4b05-bbb0-fee059e0d3b8", "type": "concept", "title": "Public discourse and cultural conflict"}], "description": "Students learn how media participate in shared meaning and everyday life."}, {"id": "fcd471fb-550c-412b-a1e6-7c3e7364b646", "type": "subtopic", "title": "Public life", "children": [{"id": "3dffe80c-0c9c-428c-88e3-dfe160cc40f3", "type": "concept", "title": "Democracy, citizenship, accountability, and public spheres"}, {"id": "dd6f23df-98f9-4f33-ab9a-e2196c1ed1ab", "type": "concept", "title": "Agenda-setting and social visibility"}, {"id": "def356e5-d133-4033-813e-f7abd37c947e", "type": "concept", "title": "Media access, exclusion, and participation"}], "description": "Mass media shape what societies know, debate, and remember."}]}, {"id": "40f5b49c-0cd5-438c-813a-1b6d74c7f0b8", "type": "topic", "title": "Media History and Technological Change from Print to Platforms", "description": "This topic traces how media technologies and institutions changed society from print through streaming and platforms.", "children": [{"id": "7c3c074f-5689-41a8-9e36-f87b4244b4eb", "type": "subtopic", "title": "Historical development", "children": [{"id": "76b7f02c-251c-4b35-89de-a00102d822eb", "type": "concept", "title": "Printing press, newspapers, telegraph, photography, radio, film, TV, internet, mobile, and platforms"}, {"id": "774063c7-9e5c-4f28-873c-27a6bfc313f6", "type": "concept", "title": "Convergence and remediation"}, {"id": "523b7937-698e-4757-bbb9-d9d02382a817", "type": "concept", "title": "Media revolutions and continuity"}], "description": "Students track how media forms emerge from social, economic, and technological change."}, {"id": "fef85a0a-114f-44c4-aeb1-b1ad4e07d3a3", "type": "subtopic", "title": "Technology and society", "children": [{"id": "54ffdb20-6e64-4554-a3e7-1fc4a2efa5f2", "type": "concept", "title": "Affordances, constraints, infrastructures, and adoption"}, {"id": "f2b89661-5049-4922-a3ee-232cf8e79af6", "type": "concept", "title": "Media ecology and McLuhan"}, {"id": "7dab7125-2373-4586-ae22-c801a5459b26", "type": "concept", "title": "Social shaping of technology"}], "description": "The gist is to avoid technological determinism while still taking technology seriously."}, {"id": "51abdb3e-302c-4d4b-aa6e-a9811c22c926", "type": "subtopic", "title": "Institutional change", "children": [{"id": "8cda81bd-109c-45e2-b37c-80b2363c144b", "type": "concept", "title": "Professionalization, commercialization, consolidation, and fragmentation"}, {"id": "9b3cdedb-b21b-4087-9604-7dc61cc0a9c1", "type": "concept", "title": "From mass audience to segmented publics"}, {"id": "0d878681-63b8-408d-9118-ac8bc52b23fa", "type": "concept", "title": "Legacy media, digital-native media, and creator media"}], "description": "Media history helps explain contemporary disruption."}]}, {"id": "7de13047-b67b-4ab6-bd5a-02519a98141a", "type": "topic", "title": "Print Media, Publishing, Newspapers, Magazines, and the Public Sphere", "description": "Students study print as a foundation for journalism, literacy, public debate, and modern media economics.", "children": [{"id": "21086076-b3ec-48e7-b4a6-107bf163a837", "type": "subtopic", "title": "Newspapers and journalism", "children": [{"id": "afaacb79-2aac-46ba-8c93-381a540c3d73", "type": "concept", "title": "Penny press, partisan press, watchdog journalism, and local news"}, {"id": "abff51d8-d351-4bc1-be95-d9908e1a9f89", "type": "concept", "title": "Objectivity, beats, sourcing, and editorial judgment"}, {"id": "b1da24af-f862-4bb4-b39c-c85b117da470", "type": "concept", "title": "Decline, consolidation, nonprofit news, and local news deserts"}], "description": "Students study newspapers as civic institutions and business models."}, {"id": "8d871ae9-6c15-4b59-8dd7-48baba0e8670", "type": "subtopic", "title": "Books, magazines, and publishing", "children": [{"id": "a5b669fd-f65a-40a2-a610-2d34262c5281", "type": "concept", "title": "Book publishing, magazines, zines, and literary publics"}, {"id": "245ed725-56e5-4e48-a957-c9b10e41f6cf", "type": "concept", "title": "Gatekeeping, authorship, censorship, and distribution"}, {"id": "68971ffd-9310-48cb-8128-d84b1b9e6147", "type": "concept", "title": "Digital publishing and subscription models"}], "description": "Print culture shaped literacy, knowledge, taste, and social movements."}, {"id": "f776589a-67e9-4a3c-a668-f71a64f90c0e", "type": "subtopic", "title": "Print and public debate", "children": [{"id": "9f39de2c-0a4b-4a07-b310-58c220a21318", "type": "concept", "title": "Pamphlets, opinion pages, letters, and public controversy"}, {"id": "0873922b-d93d-4f7d-8347-1daec3629171", "type": "concept", "title": "Habermas and critiques of exclusion"}, {"id": "1194aa97-5f5a-49f3-a602-b4bc503110ce", "type": "concept", "title": "Print publics, counterpublics, and civic participation"}], "description": "Students connect print to public sphere theory and democratic deliberation."}]}, {"id": "a871adac-7c7b-42d3-932f-138e869dbd0c", "type": "topic", "title": "Radio, Audio Media, Film, Television, Cable, Satellite, and Streaming", "description": "This module examines broadcast and audiovisual media as cultural forms, industries, and everyday social practices.", "children": [{"id": "cad1badd-4b44-4a2c-aa6f-cbfdc8b2d645", "type": "subtopic", "title": "Radio and audio", "children": [{"id": "6233b7ff-e054-453f-892a-75964d11fb8e", "type": "concept", "title": "Broadcast radio, podcasting, public radio, music, and talk formats"}, {"id": "e2dceb2d-78f3-4ff3-b914-0d1cad2351ec", "type": "concept", "title": "Sound, voice, emotion, and imagination"}, {"id": "c1c23fd7-1061-4436-9f5c-75be1f840246", "type": "concept", "title": "Regulation, ownership, and audience measurement"}], "description": "Audio media show how intimacy, liveness, and mobility shape communication."}, {"id": "f18a2fc0-e2d2-4312-a89b-ecf2f0c6902b", "type": "subtopic", "title": "Film and television", "children": [{"id": "efb33735-a88b-4eee-a626-e8308741770d", "type": "concept", "title": "Hollywood, television networks, cable, reality TV, and global formats"}, {"id": "43474979-8da9-4ecc-adc4-ab9aa9b34aaf", "type": "concept", "title": "Genres, narrative conventions, and visual culture"}, {"id": "83be78e6-dea4-4c52-83da-fffb61c2cd58", "type": "concept", "title": "Representation, fandom, and social influence"}], "description": "Students examine audiovisual media as art, industry, ideology, and habit."}, {"id": "fbafb461-e8be-4a78-b0bf-7a3659dbc153", "type": "subtopic", "title": "Streaming and convergence", "children": [{"id": "5b96104d-b70f-4c1e-9d3a-055ff141426e", "type": "concept", "title": "Subscription platforms, recommendation systems, binge viewing, and fragmentation"}, {"id": "41c293ce-7c2d-4a0a-9d8c-8320489b2276", "type": "concept", "title": "Platform competition and global catalogs"}, {"id": "672d834b-4d6e-4c75-971c-60c642b57005", "type": "concept", "title": "Labor, residuals, data, and creative risk"}], "description": "Streaming changes distribution, economics, data, and audience behavior."}]}, {"id": "5237c6a4-7d4f-449c-87b2-633f7cbb6c48", "type": "topic", "title": "Internet, Digital Media, Social Media, and Networked Publics", "description": "Students learn how digital media reshape audiences, participation, identity, attention, and platform power.", "children": [{"id": "9108e50f-d328-4294-86c4-5ebce927fe00", "type": "subtopic", "title": "Networked publics", "children": [{"id": "649326a2-2d86-4e42-834b-e1f199e78869", "type": "concept", "title": "Online identity, context collapse, virality, and participatory culture"}, {"id": "d46140c1-4175-4648-94a9-b9e24bb902e6", "type": "concept", "title": "Creators, influencers, communities, and fandoms"}, {"id": "e3edbc99-b908-49e7-88ef-5eda660d08a6", "type": "concept", "title": "Attention economies and engagement metrics"}], "description": "Students learn how digital environments reshape audience, visibility, and participation."}, {"id": "dac2906b-361a-4236-a5a0-27b75ce05299", "type": "subtopic", "title": "Platform power", "children": [{"id": "1c1ce157-ff9d-421b-b1fa-e4606e631258", "type": "concept", "title": "Algorithms, moderation, recommendation, and ranking"}, {"id": "ea3049db-7aeb-4ae8-8943-a859278ee5a6", "type": "concept", "title": "Data extraction, surveillance, and targeted advertising"}, {"id": "442dea05-e3cf-404d-940e-e7e45ed2201d", "type": "concept", "title": "Platform dependency and deplatforming"}], "description": "Platforms are media infrastructures with rules, incentives, and opaque governance."}, {"id": "38650b82-44d8-4bff-9774-ee89e53425d5", "type": "subtopic", "title": "Digital social change", "children": [{"id": "d10155f7-5677-40d7-91aa-a158207c3568", "type": "concept", "title": "Hashtag activism, civic media, and networked movements"}, {"id": "995ec90b-a6f8-4ad3-9686-96ab338c28c3", "type": "concept", "title": "Harassment, polarization, and amplification"}, {"id": "b1a7b2ab-a753-48af-8bea-63ea952b7d73", "type": "concept", "title": "Digital divides and access inequality"}], "description": "Digital media can mobilize publics and intensify harm."}]}, {"id": "925f802d-af42-4455-ab7c-e7fdd10ef9fe", "type": "topic", "title": "Media Industries, Ownership, Regulation, Policy, and Economics", "description": "This topic analyzes who owns media, how money flows, and how policy shapes public communication.", "children": [{"id": "808e6522-08ce-416d-814c-ee9c808ea850", "type": "subtopic", "title": "Ownership and concentration", "children": [{"id": "560fbc9f-7b69-42ea-81a2-241f17d40a25", "type": "concept", "title": "Conglomerates, mergers, chains, private equity, and public media"}, {"id": "9c617bda-5166-4d3c-9cb3-c51746112a33", "type": "concept", "title": "Vertical and horizontal integration"}, {"id": "8c49e2e8-9a3f-4293-bd4b-725f19f498d8", "type": "concept", "title": "Local ownership, diversity, and editorial autonomy"}], "description": "Students learn how ownership structures influence media diversity and independence."}, {"id": "90dec43c-a862-4d37-8395-912779932c90", "type": "subtopic", "title": "Media economics", "children": [{"id": "2f2fef60-ab03-48b9-8a3e-271c116d0aeb", "type": "conc